<?php
declare(strict_types=1);
class HttpError extends RuntimeException { public function __construct(string $message,public int $status=400){parent::__construct($message);} }
final class Store {
    public Database $db;
    public bool $demo;
    public function __construct(?Database $db=null) {
        $this->db=$db??new Database();$this->demo=getenv('APP_ENV')!=='production';
        if($this->demo){$this->db->migrate();require_once __DIR__.'/Seed.php';seedCatalog($this->db);}
        $_SESSION['csrf']??=bin2hex(random_bytes(32));$_SESSION['guest_token']??=bin2hex(random_bytes(32));
    }
    public function session(): array{return ['user'=>$this->user(),'csrf'=>$_SESSION['csrf'],'demo'=>$this->demo];}
    public function user(): ?array {
        if(empty($_SESSION['user_id']))return null;
        $u=$this->db->one('SELECT id,name,email,role,created_at,password_hash FROM users WHERE id=?',[$_SESSION['user_id']]);
        if(!$u||empty($_SESSION['auth_fingerprint'])||!hash_equals(hash('sha256',$u['password_hash']),(string)$_SESSION['auth_fingerprint'])){
            unset($_SESSION['user_id'],$_SESSION['auth_fingerprint']);
            $_SESSION['guest_token']=bin2hex(random_bytes(32));$_SESSION['csrf']=bin2hex(random_bytes(32));return null;
        }
        unset($u['password_hash']);return $u;
    }
    public function requireUser(): array {$u=$this->user();if(!$u)throw new HttpError('Please sign in to continue.',401);return $u;}
    public function requireAdmin(): array {$u=$this->requireUser();if(!in_array($u['role'],['admin','super_admin'],true))throw new HttpError('Administrator access required.',403);return $u;}
    public function csrf(?string $token):void{if(!$token||!hash_equals($_SESSION['csrf'],$token))throw new HttpError('Your session expired. Refresh and try again.',419);}
    private function text(array $d,string $key,int $max=200,bool $required=true):string{$v=trim((string)($d[$key]??''));if(($required&&$v==='')||mb_strlen($v)>$max)throw new HttpError('Please provide a valid '.str_replace('_',' ',$key).'.');return $v;}
    private function email(string $v):string{$v=strtolower(trim($v));if(strlen($v)>254||!filter_var($v,FILTER_VALIDATE_EMAIL))throw new HttpError('Please enter a valid email address.');return $v;}
    private function now():string{return gmdate('c');}
    private function id(array $data,string $key='id'):int{$v=filter_var($data[$key]??null,FILTER_VALIDATE_INT);if(!$v||$v<1)throw new HttpError('Invalid '.str_replace('_',' ',$key).'.');return $v;}
    public function limit(string $key,int $max=10,int $seconds=900):void{
        $bucket=hash('sha256',$key);$now=time();
        // Conditional updates prevent concurrent requests from exceeding a checked limit.
        if($this->db->run('UPDATE rate_limits SET hits=1,expires_at=? WHERE bucket=? AND expires_at<=?',[$now+$seconds,$bucket,$now])->rowCount()===1)return;
        if($this->db->run('UPDATE rate_limits SET hits=hits+1 WHERE bucket=? AND expires_at>? AND hits<?',[$bucket,$now,$max])->rowCount()===1)return;
        if(!$this->db->one('SELECT bucket FROM rate_limits WHERE bucket=?',[$bucket])){
            try{$this->db->run('INSERT INTO rate_limits(bucket,hits,expires_at) VALUES(?,1,?)',[$bucket,$now+$seconds]);return;}
            catch(PDOException $e){if(!in_array((string)$e->getCode(),['23000','23505'],true))throw $e;}
            if($this->db->run('UPDATE rate_limits SET hits=hits+1 WHERE bucket=? AND expires_at>? AND hits<?',[$bucket,$now,$max])->rowCount()===1)return;
        }
        throw new HttpError('Too many attempts. Please try again later.',429);
    }
    public function register(array $d):array{
        $this->limit('register:'.($_SERVER['REMOTE_ADDR']??'cli'),12,3600);$name=$this->text($d,'name',120);$email=$this->email($d['email']??'');$password=(string)($d['password']??'');
        if(strlen($password)<12||strlen($password)>128)throw new HttpError('Use a password between 12 and 128 characters.');
        if($this->db->one('SELECT id FROM users WHERE email=?',[$email]))throw new HttpError('This email cannot be registered. Sign in or reset your password.',409);
        $id=$this->db->insert('users',['name'=>$name,'email'=>$email,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>'customer','created_at'=>$this->now()]);
        $this->prepareIdentity($id);session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['auth_fingerprint']=hash('sha256',$this->db->one('SELECT password_hash FROM users WHERE id=?',[$id])['password_hash']);$_SESSION['csrf']=bin2hex(random_bytes(32));$this->linkCart($id);$this->queueEmail($email,'welcome',['name'=>$name],'welcome-'.$id);return $this->session();
    }
    public function login(array $d):array {
        $email=$this->email($d['email']??'');$this->limit('login-ip:'.($_SERVER['REMOTE_ADDR']??'cli'),30);$this->limit('login:'.$email,10);
        $u=$this->db->one('SELECT * FROM users WHERE email=?',[$email]);$hash=$u['password_hash']??'$2y$12$eD.XiC4y1S32uQGgW0YfceE9HU9K/JiC01k6iJUUTpRCudM4gP41.';
        if(!password_verify((string)($d['password']??''),$hash)||!$u)throw new HttpError('The email or password is incorrect.',401);
        $this->prepareIdentity((int)$u['id']);session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['auth_fingerprint']=hash('sha256',$u['password_hash']);$_SESSION['csrf']=bin2hex(random_bytes(32));$this->linkCart((int)$u['id']);return $this->session();
    }
    public function logout():array {$_SESSION=[];session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));$_SESSION['guest_token']=bin2hex(random_bytes(32));return $this->session();}
    public function forgot(array $d):array {
        $email=$this->email($d['email']??'');$this->limit('forgot:'.($_SERVER['REMOTE_ADDR']??'cli'),5,3600);$u=$this->db->one('SELECT id FROM users WHERE email=?',[$email]);
        if($u){$token=bin2hex(random_bytes(32));$this->db->run('DELETE FROM password_resets WHERE user_id=?',[$u['id']]);$this->db->run('INSERT INTO password_resets(token_hash,user_id,expires_at) VALUES(?,?,?)',[hash('sha256',$token),$u['id'],gmdate('c',time()+3600)]);$this->queueEmail($email,'password_reset',['token'=>$token],'reset-'.hash('sha256',$token));}
        return ['message'=>'If this account exists, a password reset email has been queued. Delivery depends on the configured email service.'];
    }
    public function resetPassword(array $d):array {
        $this->limit('reset:'.($_SERVER['REMOTE_ADDR']??'cli'),10);$token=$this->text($d,'token',128);$password=(string)($d['password']??'');if(strlen($password)<12||strlen($password)>128)throw new HttpError('Use a password between 12 and 128 characters.');
        $this->db->transaction(function()use($token,$password){$r=$this->db->one('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>?'.($this->db->mysql?' FOR UPDATE':''),[hash('sha256',$token),$this->now()]);if(!$r)throw new HttpError('This reset link is invalid or expired.');$this->db->run('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$r['user_id']]);$this->db->run('UPDATE password_resets SET used_at=? WHERE token_hash=?',[$this->now(),hash('sha256',$token)]);});return ['message'=>'Your password has been reset. Please sign in.'];
    }
    public function categories():array{return $this->db->all('SELECT * FROM categories ORDER BY position,id');}
    private function baseSelect():string{return 'SELECT p.*,v.id variant_id,v.sku internal_sku,v.label variant_label,v.price_cents,v.dealer_price_cents,v.old_price_cents,v.stock,v.attributes,v.stock_verified_at,c.name category,c.slug category_slug,b.name brand FROM products p JOIN product_variants v ON v.product_id=p.id JOIN categories c ON c.id=p.category_id JOIN brands b ON b.id=p.brand_id';}
    private function normalize(array $p):array{
        $p['id']=(int)$p['id'];$p['variant_id']=(int)$p['variant_id'];$p['price_cents']=(int)$p['price_cents'];$p['old_price_cents']=$p['old_price_cents']!==null?(int)$p['old_price_cents']:null;$p['stock']=(int)$p['stock'];$p['is_demo']=(bool)$p['is_demo'];
        $p['specs']=json_decode($p['specs'],true)?:[];$attrs=json_decode($p['attributes'],true)?:[];$p['sku']=$attrs['source_sku']??$p['internal_sku'];$p['fixture']=$attrs['fixture']??false;
        if(($this->user()['role']??'')==='dealer'&&$p['dealer_price_cents']!==null){$p['price_cents']=(int)$p['dealer_price_cents'];$p['price_type']='dealer';}else$p['price_type']='retail';
        unset($p['dealer_price_cents'],$p['internal_sku'],$p['attributes']);return $p;
    }
    public function catalog(array $f=[]):array{
        $where=['p.active=1','v.id=(SELECT MIN(v2.id) FROM product_variants v2 WHERE v2.product_id=p.id)'];$params=[];$priceColumn=($this->user()['role']??'')==='dealer'?'COALESCE(v.dealer_price_cents,v.price_cents)':'v.price_cents';
        if(!empty($f['q'])){$q='%'.str_replace(['%','_'],['\\%','\\_'],mb_substr((string)$f['q'],0,100)).'%';$where[]='(p.name LIKE ? OR v.sku LIKE ? OR b.name LIKE ?)';array_push($params,$q,$q,$q);}
        foreach(['category'=>'c.slug','brand'=>'b.name'] as $key=>$col)if(!empty($f[$key])){$where[]="$col=?";$params[]=$f[$key];}
        if(isset($f['min'])&&is_numeric($f['min'])){$where[]=$priceColumn.'>=?';$params[]=(int)$f['min']*100;}
        if(isset($f['max'])&&is_numeric($f['max'])){$where[]=$priceColumn.'<=?';$params[]=(int)$f['max']*100;}
        if(!empty($f['stock']))$where[]='v.stock>0';
        $sql=$this->baseSelect().' WHERE '.implode(' AND ',$where);$total=(int)$this->db->run('SELECT COUNT(*) FROM ('.$sql.') catalog_count',$params)->fetchColumn();
        $sort=['featured'=>'p.featured DESC,p.id','price-asc'=>$priceColumn.' ASC','price-desc'=>$priceColumn.' DESC','name'=>'p.name ASC','newest'=>'p.id DESC'][$f['sort']??'featured']??'p.featured DESC,p.id';
        $page=max(1,(int)($f['page']??1));$limit=min(100,max(1,(int)($f['limit']??24)));$offset=($page-1)*$limit;
        $rows=$this->db->all($sql.' ORDER BY '.$sort.' LIMIT '.$limit.' OFFSET '.$offset,$params);
        return ['products'=>array_map(fn($p)=>$this->normalize($p),$rows),'total'=>$total,'categories'=>$this->categories(),'brands'=>array_column($this->db->all("SELECT name FROM brands WHERE name<>'Demo fixtures' ORDER BY name"),'name'),'page'=>$page,'pages'=>(int)ceil($total/$limit)];
    }
    public function product(string $slug):?array{$rows=$this->db->all($this->baseSelect().' WHERE p.slug=? AND p.active=1 ORDER BY v.id',[$slug]);if(!$rows)return null;$all=array_map(fn($p)=>$this->normalize($p),$rows);$p=$all[0];$p['variants']=$all;$p['images']=$this->db->all('SELECT url,alt FROM product_images WHERE product_id=? ORDER BY position',[$p['id']]);return $p;}
    public function variant(int $id):array{$p=$this->db->one($this->baseSelect().' WHERE v.id=? AND p.active=1',[$id]);if(!$p)throw new HttpError('This product is no longer available.',404);return $this->normalize($p);}
    private function cartRecord():array {
        $user=$this->user();$token=$_SESSION['guest_token'];$c=$this->db->one('SELECT * FROM carts WHERE token=?',[$token]);
        if($c&&!empty($c['user_id'])&&(!$user||(int)$c['user_id']!==(int)$user['id'])){$_SESSION['guest_token']=bin2hex(random_bytes(32));$token=$_SESSION['guest_token'];$c=null;}
        if($c&&strtotime($c['updated_at'])<time()-86400){$this->db->run('DELETE FROM cart_items WHERE cart_id=?',[$c['id']]);$this->db->run('UPDATE carts SET updated_at=? WHERE id=?',[$this->now(),$c['id']]);$c['updated_at']=$this->now();}
        if(!$c){$id=$this->db->insert('carts',['token'=>$token,'user_id'=>$this->user()['id']??null,'updated_at'=>$this->now()]);$c=$this->db->one('SELECT * FROM carts WHERE id=?',[$id]);}return $c;
    }
    private function prepareIdentity(int $id):void {
        if(!empty($_SESSION['user_id'])&&(int)$_SESSION['user_id']!==$id)$_SESSION['guest_token']=bin2hex(random_bytes(32));
    }
    private function linkCart(int $id):void {
        $this->db->transaction(function()use($id){
            $lock=$this->db->mysql?' FOR UPDATE':'';
            // Serialize account merges, then lock its carts in stable identity order.
            $this->db->one('SELECT id FROM users WHERE id=?'.$lock,[$id]);
            $current=$this->cartRecord();
            $this->db->run('UPDATE carts SET user_id=? WHERE id=? AND user_id IS NULL',[$id,$current['id']]);
            $carts=$this->db->all('SELECT * FROM carts WHERE user_id=? ORDER BY id'.$lock,[$id]);$totals=[];
            foreach($carts as $cart){
                if(strtotime($cart['updated_at'])<time()-86400)continue;
                foreach($this->db->all('SELECT variant_id,quantity FROM cart_items WHERE cart_id=?',[$cart['id']]) as $item){
                    $variant=(int)$item['variant_id'];$totals[$variant]=min(100,($totals[$variant]??0)+(int)$item['quantity']);
                }
            }
            $this->db->run('DELETE FROM cart_items WHERE cart_id=?',[$current['id']]);
            foreach($totals as $variant=>$quantity){
                $stock=$this->db->one('SELECT v.stock FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id=? AND p.active=1',[$variant]);
                $quantity=min($quantity,(int)($stock['stock']??0));
                if($quantity>0)$this->db->insert('cart_items',['cart_id'=>$current['id'],'variant_id'=>$variant,'quantity'=>$quantity]);
            }
            $this->db->run('DELETE FROM carts WHERE user_id=? AND id<>?',[$id,$current['id']]);
            $this->db->run('UPDATE carts SET updated_at=? WHERE id=?',[$this->now(),$current['id']]);
            $this->db->run('UPDATE wishlists SET user_id=? WHERE guest_token=? AND user_id IS NULL',[$id,$_SESSION['guest_token']]);
        });
    }
    public function cart():array {
        $c=$this->cartRecord();$items=[];$total=0;$count=0;
        foreach($this->db->all('SELECT variant_id,quantity FROM cart_items WHERE cart_id=?',[$c['id']]) as $i){$p=$this->variant((int)$i['variant_id']);$p['quantity']=(int)$i['quantity'];$p['line_total_cents']=$p['quantity']*$p['price_cents'];$items[]=$p;$total+=$p['line_total_cents'];$count+=$p['quantity'];}
        $coupon=$this->db->one('SELECT cp.code,cp.percent FROM cart_coupons cc JOIN coupons cp ON cp.code=cc.code WHERE cc.cart_id=? AND cp.active=1 AND cp.expires_at>?',[$c['id'],$this->now()]);
        if(($this->user()['role']??'')==='dealer')$coupon=null;
        $discount=$coupon?intdiv($total*(int)$coupon['percent'],100):0;
        return ['items'=>$items,'subtotal_cents'=>$total,'discount_cents'=>$discount,'coupon'=>$coupon,'total_cents'=>$total-$discount,'count'=>$count,'expires_at'=>gmdate('c',strtotime($c['updated_at'])+86400),'demo'=>$this->demo,'shipping_cents'=>null];
    }
    public function updateCart(array $d,bool $increment=false):array {
        $id=$this->id($d,'variant_id');$q=filter_var($d['quantity']??1,FILTER_VALIDATE_INT);if($q===false||$q<0||$q>100)throw new HttpError('Choose a quantity between 0 and 100.');$c=$this->cartRecord();$p=$this->variant($id);
        if($increment)$q+=(int)($this->db->one('SELECT quantity FROM cart_items WHERE cart_id=? AND variant_id=?',[$c['id'],$id])['quantity']??0);
        if($q>100)throw new HttpError('Choose a quantity between 0 and 100.');
        if($q>$p['stock'])throw new HttpError('The requested quantity is not available.',409);
        $this->db->transaction(function()use($c,$id,$q){$this->db->run('DELETE FROM cart_items WHERE cart_id=? AND variant_id=?',[$c['id'],$id]);if($q>0)$this->db->insert('cart_items',['cart_id'=>$c['id'],'variant_id'=>$id,'quantity'=>$q]);$this->db->run('UPDATE carts SET updated_at=? WHERE id=?',[$this->now(),$c['id']]);});return $this->cart();
    }
    public function wishlist():array {$u=$this->user();$rows=$this->db->all('SELECT DISTINCT product_id FROM wishlists WHERE guest_token=?'.($u?' OR user_id=?':''),$u?[$_SESSION['guest_token'],$u['id']]:[$_SESSION['guest_token']]);$products=[];foreach($rows as $r){$p=$this->db->one('SELECT slug FROM products WHERE id=?',[$r['product_id']]);if($p&&($product=$this->product($p['slug'])))$products[]=$product;}return ['products'=>$products];}
    public function toggleWishlist(array $d):array {$id=$this->id($d,'product_id');if(!$this->db->one('SELECT id FROM products WHERE id=? AND active=1',[$id]))throw new HttpError('Product not found.',404);$u=$this->user();$row=$this->db->one('SELECT product_id FROM wishlists WHERE product_id=? AND (guest_token=?'.($u?' OR user_id=?':'').')',$u?[$id,$_SESSION['guest_token'],$u['id']]:[$id,$_SESSION['guest_token']]);if($row)$this->db->run('DELETE FROM wishlists WHERE product_id=? AND (guest_token=?'.($u?' OR user_id=?':'').')',$u?[$id,$_SESSION['guest_token'],$u['id']]:[$id,$_SESSION['guest_token']]);else$this->db->insert('wishlists',['user_id'=>$u['id']??null,'guest_token'=>$_SESSION['guest_token'],'product_id'=>$id]);return $this->wishlist();}
    public function checkout(array $d):array {
        $key=$this->text($d,'idempotency_key',100);if(strlen($key)<16)throw new HttpError('Invalid checkout reference.');$user=$this->user();$method=$d['payment_method']??'eft';
        if(!in_array($method,['eft','payfast'],true))throw new HttpError('Select a supported payment method.');
        if(($user['role']??'')==='dealer'&&$method!=='eft')throw new HttpError('Approved dealer orders require EFT.',403);
        if($method==='payfast')throw new HttpError('Online payments are awaiting merchant verification. Please use the available test EFT flow.',503);
        if(!$this->demo)throw new HttpError('Live checkout is closed until inventory, banking and shipping have passed production verification.',503);
        $existing=$this->db->one('SELECT * FROM orders WHERE idempotency_key=?',[$key]);if($existing){$this->assertOwner($existing);return ['order'=>$this->order((int)$existing['id'])];}
        $customer=['name'=>$this->text($d,'name',120),'email'=>$this->email($d['email']??''),'phone'=>$this->text($d,'phone',40),'address'=>$this->text($d,'address',500),'city'=>$this->text($d,'city',120),'postal_code'=>$this->text($d,'postal_code',15)];$delivery=$d['delivery']??'quote';if(!in_array($delivery,['quote','collection'],true))throw new HttpError('Select delivery or collection.');
        $result=$this->db->transaction(function()use($key,$user,$method,$customer,$delivery){
            $lockedCart=$this->cartRecord();$this->db->one('SELECT id FROM carts WHERE id=?'.($this->db->mysql?' FOR UPDATE':''),[$lockedCart['id']]);
            if($this->db->mysql)$this->db->all('SELECT v.id FROM product_variants v JOIN cart_items ci ON ci.variant_id=v.id WHERE ci.cart_id=? ORDER BY v.id FOR UPDATE',[$lockedCart['id']]);
            $cart=$this->cart();if(!$cart['items'])throw new HttpError('Your cart is empty.');
            foreach($cart['items'] as $p){$count=$this->db->run('UPDATE product_variants SET stock=stock-? WHERE id=? AND stock>=?',[$p['quantity'],$p['variant_id'],$p['quantity']])->rowCount();if($count!==1)throw new HttpError('Stock changed for '.$p['name'].'. Please review your cart.',409);}
            $number='TEST-'.gmdate('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$id=$this->db->insert('orders',['number'=>$number,'user_id'=>$user['id']??null,'guest_token'=>$_SESSION['guest_token'],'idempotency_key'=>$key,'customer_snapshot'=>json_encode($customer+['coupon'=>$cart['coupon'],'discount_cents'=>$cart['discount_cents']]),'subtotal_cents'=>$cart['subtotal_cents'],'shipping_cents'=>null,'total_cents'=>$cart['total_cents'],'status'=>'pending_payment','payment_method'=>$method,'delivery'=>$delivery,'is_demo'=>1,'created_at'=>$this->now(),'updated_at'=>$this->now()]);
            foreach($cart['items'] as $p)$this->db->insert('order_items',['order_id'=>$id,'variant_id'=>$p['variant_id'],'sku'=>$p['sku'],'name'=>$p['name'],'quantity'=>$p['quantity'],'unit_price_cents'=>$p['price_cents'],'line_total_cents'=>$p['line_total_cents'],'specifications'=>json_encode($p['specs'])]);
            $c=$this->cartRecord();$this->db->run('DELETE FROM cart_items WHERE cart_id=?',[$c['id']]);$this->db->run('DELETE FROM cart_coupons WHERE cart_id=?',[$c['id']]);$this->queueEmail($customer['email'],'order_confirmation',['order_id'=>$id,'is_demo'=>true],'order-'.$id);return $id;
        });return ['order'=>$this->order($result)];
    }
    private function assertOwner(array $row):void { $u=$this->user();if($u&&in_array($u['role'],['admin','super_admin'],true))return;if(!empty($row['user_id'])){if($u&&(int)$row['user_id']===(int)$u['id'])return;throw new HttpError('Record not found.',404);}if(!empty($row['guest_token'])&&hash_equals($row['guest_token'],$_SESSION['guest_token']))return;throw new HttpError('Record not found.',404); }
    public function order(int $id):array {$o=$this->db->one('SELECT * FROM orders WHERE id=?',[$id]);if(!$o)throw new HttpError('Order not found.',404);$this->assertOwner($o);$o['items']=$this->db->all('SELECT * FROM order_items WHERE order_id=?',[$id]);$o['customer']=json_decode($o['customer_snapshot'],true);unset($o['guest_token'],$o['idempotency_key'],$o['customer_snapshot']);return $o;}
    public function applyDealer(array $d):array {$u=$this->requireUser();if(!in_array($u['role'],['customer','pending_dealer'],true))throw new HttpError('Your account already has a business or staff role.',409);$data=['business_name'=>$this->text($d,'business_name',200),'registration_number'=>$this->text($d,'registration_number',120),'vat_number'=>$this->text($d,'vat_number',120,false),'contact_name'=>$this->text($d,'contact_name',120),'phone'=>$this->text($d,'phone',40),'address'=>$this->text($d,'address',1000)];
        $this->db->transaction(function()use($u,$data){$existing=$this->db->one('SELECT id FROM dealer_applications WHERE user_id=?',[$u['id']]);if($existing)throw new HttpError('Your application has already been submitted.',409);$this->db->insert('dealer_applications',$data+['user_id'=>$u['id'],'status'=>'pending','created_at'=>$this->now()]);$this->db->run("UPDATE users SET role='pending_dealer' WHERE id=?",[$u['id']]);});return ['message'=>'Application received. Dealer access remains pending administrator approval.','application'=>$this->db->one('SELECT * FROM dealer_applications WHERE user_id=?',[$u['id']])];}
    public function buildOptions():array {$groups=array_fill_keys(Builder::GROUPS,[]);foreach($this->catalog(['category'=>'components','limit'=>100])['products'] as $p){$type=$p['specs']['component_type']??null;if($type&&isset($groups[$type]))$groups[$type][]=$p;}return ['groups'=>$groups];}
    public function validateBuild(array $components):array {$parts=[];foreach($components as $group=>$id){if(!in_array($group,Builder::GROUPS,true))throw new HttpError('Unknown component group.');if(!$id)continue;$p=$this->variant((int)$id);if(($p['specs']['component_type']??null)!==$group)throw new HttpError('The selected part does not belong in '.$group.'.');$parts[$group]=$p;}return Builder::validate($parts);}
    public function saveBuild(array $d):array {$u=$this->requireUser();$build=$this->validateBuild((array)($d['components']??[]));if(!$build['components'])throw new HttpError('Select at least one component.');$token=bin2hex(random_bytes(16));$id=$this->db->transaction(function()use($u,$d,$build,$token){$id=$this->db->insert('pc_builds',['user_id'=>$u['id'],'share_token'=>$token,'name'=>$this->text($d,'name',160),'purpose'=>$this->text($d,'purpose',80,false)?:'custom','budget_cents'=>max(0,(int)($d['budget_cents']??0)),'created_at'=>$this->now()]);foreach($build['components'] as $g=>$p)$this->db->insert('pc_build_components',['build_id'=>$id,'component_type'=>$g,'variant_id'=>$p['variant_id']]);return $id;});return ['id'=>$id,'share_token'=>$token,'url'=>'/build/'.$token]+$build;}
    public function sharedBuild(string $token):array {$b=$this->db->one('SELECT id,name,purpose,budget_cents,share_token FROM pc_builds WHERE share_token=?',[$token]);if(!$b)throw new HttpError('Build not found.',404);$c=[];foreach($this->db->all('SELECT component_type,variant_id FROM pc_build_components WHERE build_id=?',[$b['id']]) as $p)$c[$p['component_type']]=$p['variant_id'];return $b+$this->validateBuild($c);}
