    public function createQuote(array $d):array {$u=$this->user();$items=($d['source']??'cart')==='build'?array_values($this->validateBuild((array)($d['components']??[]))['components']):$this->cart()['items'];if(!$items)throw new HttpError('Add products before requesting a quotation.');$customer=['name'=>$d['name']??$u['name']??'Guest customer','email'=>isset($d['email'])?$this->email($d['email']):($u['email']??''),'notes'=>mb_substr((string)($d['notes']??''),0,2000)];$total=0;foreach($items as $p)$total+=$p['price_cents']*($p['quantity']??1);if(($d['source']??'cart')==='cart'){$cartSummary=$this->cart();$customer['discount_cents']=$cartSummary['discount_cents'];$customer['coupon']=$cartSummary['coupon'];$total=$cartSummary['total_cents'];}$id=$this->db->transaction(function()use($u,$items,$customer,$total){$id=$this->db->insert('quotes',['number'=>($this->demo?'DEMO-':'').'Q-'.gmdate('ymd').'-'.strtoupper(bin2hex(random_bytes(4))),'user_id'=>$u['id']??null,'guest_token'=>$_SESSION['guest_token'],'customer_snapshot'=>json_encode($customer),'total_cents'=>$total,'status'=>'draft','expires_at'=>gmdate('c',time()+7*86400),'created_at'=>$this->now()]);foreach($items as $p)$this->db->insert('quote_items',['quote_id'=>$id,'variant_id'=>$p['variant_id'],'sku'=>$p['sku'],'name'=>$p['name'],'quantity'=>$p['quantity']??1,'unit_price_cents'=>$p['price_cents'],'line_total_cents'=>$p['price_cents']*($p['quantity']??1)]);return $id;});return ['id'=>$id,'number'=>$this->db->one('SELECT number FROM quotes WHERE id=?',[$id])['number'],'total_cents'=>$total,'pdf_url'=>'/api/quotes/'.$id.'/pdf','status'=>'draft'];}
