    public function consent(array $d):array {$u=$this->user();$email=$this->email($u['email']??$d['email']??'');$consent=filter_var($d['consent']??false,FILTER_VALIDATE_BOOL);$this->db->transaction(function()use($u,$email,$consent){$this->db->run('DELETE FROM marketing_consents WHERE email=?',[$email]);$this->db->insert('marketing_consents',['email'=>$email,'user_id'=>$u['id']??null,'consent'=>$consent?1:0,'source'=>'explicit_web_form','updated_at'=>$this->now()]);});return ['message'=>$consent?'Your email preference has been saved.':'You have been unsubscribed.','consent'=>$consent];}
