    public function dashboard():array {$this->requireAdmin();$metrics=['orders'=>(int)$this->db->run('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending_eft'=>(int)$this->db->run("SELECT COUNT(*) FROM orders WHERE status='pending_payment' AND payment_method='eft'")->fetchColumn(),'revenue_cents'=>(int)$this->db->run("SELECT COALESCE(SUM(total_cents),0) FROM orders WHERE status IN ('paid','processing','ready_for_dispatch','shipped','delivered') AND is_demo=0")->fetchColumn(),'customers'=>(int)$this->db->run('SELECT COUNT(*) FROM users')->fetchColumn(),'pending_dealers'=>(int)$this->db->run("SELECT COUNT(*) FROM dealer_applications WHERE status='pending'")->fetchColumn(),'open_tickets'=>(int)$this->db->run("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')")->fetchColumn(),'low_stock'=>(int)$this->db->run('SELECT COUNT(*) FROM product_variants WHERE stock<3')->fetchColumn(),'abandoned_carts'=>(int)$this->db->run('SELECT COUNT(*) FROM carts WHERE updated_at<?',[gmdate('c',time()-3600)])->fetchColumn()];return ['metrics'=>$metrics,'categories'=>$this->categories(),'coupons'=>$this->db->all('SELECT * FROM coupons ORDER BY code'),'products'=>$this->catalog(['limit'=>100])['products'],'orders'=>$this->db->all('SELECT id,number,total_cents,status,payment_method,is_demo,created_at FROM orders ORDER BY id DESC LIMIT 100'),'dealers'=>$this->db->all('SELECT d.*,u.email FROM dealer_applications d JOIN users u ON u.id=d.user_id ORDER BY d.id DESC LIMIT 100'),'tickets'=>$this->db->all('SELECT * FROM support_tickets ORDER BY id DESC LIMIT 100'),'campaigns'=>$this->db->all('SELECT * FROM email_campaigns ORDER BY id DESC LIMIT 50'),'quotes'=>$this->db->all('SELECT id,number,total_cents,status,expires_at FROM quotes ORDER BY id DESC LIMIT 100'),'settings'=>$this->settings(),'integrations'=>array_fill_keys(['Fincon','PayFast','Bob Go','Internet Express','Pargo','Email','AI'],'Credentials and acceptance tests pending'),'demo'=>$this->demo];}
    public function adminProduct(array $d):array {$this->requireAdmin();$name=$this->text($d,'name',220);$slug=$this->text($d,'slug',180);if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))throw new HttpError('Use a URL-safe lowercase product slug.');$brandName=$this->text($d,'brand',120);$category=$this->db->one('SELECT id FROM categories WHERE slug=?',[$d['category_slug']??'']);if(!$category)throw new HttpError('Select an existing category.');$price=filter_var($d['price_cents']??null,FILTER_VALIDATE_INT);$stock=filter_var($d['stock']??null,FILTER_VALIDATE_INT);if($price===false||$price<0||$price>10000000000||$stock===false||$stock<0||$stock>1000000)throw new HttpError('Supply valid integer prices and stock.');$image=$this->text($d,'image',500,false);if($image!==''&&!preg_match('#^/assets/[a-zA-Z0-9/_.-]+$#',$image))throw new HttpError('Use an approved local /assets/ image path.');
        $id=$this->db->transaction(function()use($d,$name,$slug,$brandName,$category,$price,$stock,$image){$brand=$this->db->one('SELECT id FROM brands WHERE name=?',[$brandName]);$bid=$brand['id']??$this->db->insert('brands',['name'=>$brandName]);$specs=$d['specs']??[];if(!is_array($specs))throw new HttpError('Specifications must be an object.');$values=['category_id'=>$category['id'],'brand_id'=>$bid,'slug'=>$slug,'name'=>$name,'description'=>$this->text($d,'description',20000,false),'image'=>$image,'specs'=>json_encode($specs),'active'=>isset($d['active'])?(int)(bool)$d['active']:1];$id=isset($d['id'])&&$d['id']!==''?$this->id($d):0;
            if($id){if(!$this->db->one('SELECT id FROM products WHERE id=?',[$id]))throw new HttpError('Product not found.',404);$sets=implode(',',array_map(fn($k)=>$k.'=?',array_keys($values)));$this->db->run('UPDATE products SET '.$sets.' WHERE id=?',[...array_values($values),$id]);$v=$this->db->one('SELECT id FROM product_variants WHERE product_id=? ORDER BY id LIMIT 1',[$id]);$this->db->run('UPDATE product_variants SET price_cents=?,stock=? WHERE id=?',[$price,$stock,$v['id']]);}
            else{$id=$this->db->insert('products',$values+['is_demo'=>$this->demo?1:0,'featured'=>0,'created_at'=>$this->now()]);$sku=$this->text($d,'sku',100);$this->db->insert('product_variants',['product_id'=>$id,'sku'=>$sku,'label'=>'Standard','price_cents'=>$price,'stock'=>$stock,'attributes'=>json_encode(['source_sku'=>$sku])]);}$this->audit('product.saved','product:'.$id,['price_cents'=>$price,'stock'=>$stock]);return $id;});return $this->product($slug)??['id'=>$id];
    }
    public function adminDealer(array $d):array {$u=$this->requireAdmin();$id=$this->id($d);$status=$d['status']??'';if(!in_array($status,['approved','rejected','information_requested'],true))throw new HttpError('Invalid application status.');$application=$this->db->one('SELECT * FROM dealer_applications WHERE id=?',[$id]);if(!$application)throw new HttpError('Application not found.',404);$this->db->transaction(function()use($d,$id,$status,$u,$application){$this->db->run('UPDATE dealer_applications SET status=?,reviewed_by=?,fincon_account=? WHERE id=?',[$status,$u['id'],$this->text($d,'fincon_account',100,false),$id]);$this->db->run('UPDATE users SET role=? WHERE id=?',[$status==='approved'?'dealer':'pending_dealer',$application['user_id']]);$this->audit('dealer.'.$status,'dealer:'.$id);});return ['message'=>'Dealer application updated.'];}
    public function adminOrder(array $d):array {$this->requireAdmin();$id=$this->id($d);$status=$d['status']??'';$reason=$this->text($d,'reason',1000);$allowed=['pending_payment'=>['awaiting_verification','cancelled'],'awaiting_verification'=>['paid','pending_payment','cancelled'],'paid'=>['processing','refunded'],'processing'=>['ready_for_dispatch','refunded'],'ready_for_dispatch'=>['shipped','refunded'],'shipped'=>['delivered'],'delivered'=>['refunded'],'cancelled'=>[],'refunded'=>[]];
        $this->db->transaction(function()use($d,$id,$status,$reason,$allowed){$o=$this->db->one('SELECT * FROM orders WHERE id=?'.($this->db->mysql?' FOR UPDATE':''),[$id]);if(!$o)throw new HttpError('Order not found.',404);if(!in_array($status,$allowed[$o['status']]??[],true))throw new HttpError('This order state transition is not permitted.',409);
            if($status==='paid'){$reference=$this->text($d,'payment_reference',180);$this->db->insert('payments',['order_id'=>$id,'provider'=>'eft','provider_reference'=>'eft:'.$reference,'amount_cents'=>$o['total_cents'],'status'=>'verified','created_at'=>$this->now()]);}
            if($status==='refunded'&&!$o['is_demo'])throw new HttpError('Record an externally verified refund through the reconciliation workflow before updating this order.',409);
            if($status==='cancelled')foreach($this->db->all('SELECT variant_id,quantity FROM order_items WHERE order_id=?',[$id]) as $i)$this->db->run('UPDATE product_variants SET stock=stock+? WHERE id=?',[$i['quantity'],$i['variant_id']]);
            $this->db->run('UPDATE orders SET status=?,updated_at=? WHERE id=?',[$status,$this->now(),$id]);$this->audit('order.'.$status,'order:'.$id,['reason'=>$reason,'previous'=>$o['status']]);});return $this->order($id);
    }
    public function adminSetting(array $d):array {$this->requireAdmin();$key=$d['key']??'';if(!in_array($key,['announcement','company_name','contact_email','contact_phone','vat_basis','shipping_note','returns_note','privacy_note','cart_recovery_enabled','marketing_enabled'],true))throw new HttpError('This setting is not editable here. Credentials are server environment configuration.');$value=$this->text($d,'value',4000,false);$this->db->transaction(function()use($key,$value){$this->db->run('DELETE FROM settings WHERE name=?',[$key]);$this->db->run('INSERT INTO settings(name,value) VALUES(?,?)',[$key,$value]);$this->audit('settings.updated',$key);});return ['settings'=>$this->settings()];}
    public function adminCampaign(array $d):array {$u=$this->requireAdmin();$id=$this->db->insert('email_campaigns',['title'=>$this->text($d,'title',180),'subject'=>$this->text($d,'subject',220),'body'=>$this->text($d,'body',20000),'status'=>'draft','created_by'=>$u['id'],'created_at'=>$this->now()]);$this->audit('campaign.draft','campaign:'.$id);return ['id'=>$id,'status'=>'draft','message'=>'Campaign saved as a draft. Sending requires a verified email provider and consent review.'];}
    public function adminTicket(array $d):array {$this->requireAdmin();$id=$this->id($d);$status=$d['status']??'';$priority=$d['priority']??'normal';if(!in_array($status,['open','awaiting_customer','in_progress','resolved','closed'],true)||!in_array($priority,['low','normal','high','urgent'],true))throw new HttpError('Invalid ticket status or priority.');$this->db->run('UPDATE support_tickets SET status=?,priority=?,updated_at=? WHERE id=?',[$status,$priority,$this->now(),$id]);$this->audit('ticket.updated','ticket:'.$id);return $this->ticket($id);}
    public function exportOrders():string {$this->requireAdmin();$rows=$this->db->all('SELECT number,status,total_cents,payment_method,is_demo,created_at FROM orders ORDER BY id DESC LIMIT 1000');$handle=fopen('php://temp','r+');fputcsv($handle,['Order','Status','Total (cents)','Payment','Demo','Created'],',','"','');foreach($rows as $r){$r=array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,$r);fputcsv($handle,$r,',','"','');}rewind($handle);$csv=stream_get_contents($handle);fclose($handle);$this->audit('orders.export','orders',['rows'=>count($rows)]);return $csv;}
    public function recordVerifiedPayment(array $event):array {
        $reference=(string)($event['provider_id']??'');$id=filter_var($event['order_id']??null,FILTER_VALIDATE_INT);
        $amount=filter_var($event['amount_cents']??null,FILTER_VALIDATE_INT);
        if(!preg_match('/^[A-Za-z0-9_-]{1,100}$/D',$reference)||!$id||$id<1||$amount===false||$amount<0||strtolower((string)($event['status']??''))!=='complete')throw new HttpError('Invalid verified payment event.',400);
        return $this->db->transaction(function()use($event,$reference,$id,$amount){
            $key='payfast:'.$reference;$lock=$this->db->mysql?' FOR UPDATE':'';
            $o=$this->db->one('SELECT * FROM orders WHERE id=?'.$lock,[$id]);
            if(!$o||(int)$o['total_cents']!==$amount||$o['payment_method']!=='payfast')throw new HttpError('Payment amount or order mismatch.',400);
            $existing=$this->db->one('SELECT * FROM payment_events WHERE event_key=?'.$lock,[$key]);
            if($existing){if((int)$existing['order_id']!==$id)throw new HttpError('Payment reference belongs to another order.',409);return ['duplicate'=>true,'order_id'=>$id];}
            if(!in_array($o['status'],['pending_payment','awaiting_verification'],true))throw new HttpError('Order cannot accept payment in this state.',409);
            $this->db->insert('payments',['order_id'=>$id,'provider'=>'payfast','provider_reference'=>$key,'amount_cents'=>$o['total_cents'],'status'=>'verified','created_at'=>$this->now()]);
            $this->db->insert('payment_events',['provider'=>'payfast','event_key'=>$key,'order_id'=>$id,'payload_hash'=>$event['payload_sha256']??hash('sha256',json_encode($event)),'result'=>'accepted','created_at'=>$this->now()]);
            $this->db->run("UPDATE orders SET status='paid',updated_at=? WHERE id=?",[$this->now(),$id]);return ['duplicate'=>false,'order_id'=>$id];
        });
    }
    public function assistant(array $d):array {$this->limit('assistant:'.$_SESSION['guest_token'],20,3600);$message=$this->text($d,'message',1000);$words=preg_split('/\s+/',strtolower($message));$categories=['laptop'=>'laptops','notebook'=>'laptops','network'=>'networking','router'=>'networking','camera'=>'surveillance','cctv'=>'surveillance','component'=>'components','pc'=>'desktops','pos'=>'pos'];$filter=[];foreach($categories as $word=>$cat)if(str_contains(strtolower($message),$word)){$filter=['category'=>$cat];break;}if(!$filter)$filter=['q'=>$message];$results=$this->catalog($filter+['limit'=>4]);return ['mode'=>'catalog_helper','message'=>'I can show matching catalog items and their recorded specifications. Live AI advice is not connected yet. Prices are source snapshots, and stock is demonstration data. For tailored advice, open a support ticket.','products'=>$results['products'],'support_url'=>'/support'];}    public function updateProfile(array $d):array {
        $u=$this->requireUser();$name=$this->text($d,'name',120);$email=$this->email($d['email']??$u['email']);
        if($email!==$u['email'])throw new HttpError('Email changes require a verified email workflow. Keep your current email until email delivery is configured.',409);
        $this->db->run('UPDATE users SET name=? WHERE id=?',[$name,$u['id']]);return ['user'=>$this->user(),'message'=>'Your profile has been updated.'];
    }
    public function saveAddress(array $d):array {
        $u=$this->requireUser();$address=['label'=>$this->text($d,'label',80,false)?:'Address','address'=>$this->text($d,'address',1000),'city'=>$this->text($d,'city',120),'postal_code'=>$this->text($d,'postal_code',15)];
        if(!empty($d['id'])){$id=$this->id($d);if(!$this->db->one('SELECT id FROM customer_addresses WHERE id=? AND user_id=?',[$id,$u['id']]))throw new HttpError('Address not found.',404);$this->db->run('UPDATE customer_addresses SET label=?,address=?,city=?,postal_code=? WHERE id=?',[...array_values($address),$id]);}
        else{$count=(int)$this->db->run('SELECT COUNT(*) FROM customer_addresses WHERE user_id=?',[$u['id']])->fetchColumn();if($count>=20)throw new HttpError('You can save up to 20 addresses.');$id=$this->db->insert('customer_addresses',['user_id'=>$u['id']]+$address);}
        return ['addresses'=>$this->db->all('SELECT id,label,address,city,postal_code FROM customer_addresses WHERE user_id=? ORDER BY id',[$u['id']]),'message'=>'Address saved.'];
    }
    public function removeAddress(array $d):array {$u=$this->requireUser();$id=$this->id($d);$this->db->run('DELETE FROM customer_addresses WHERE id=? AND user_id=?',[$id,$u['id']]);return ['message'=>'Address removed.'];}
    public function applyCoupon(array $d):array {
        $code=strtoupper($this->text($d,'code',50,false));$c=$this->cartRecord();
        if($code!==''){$coupon=$this->db->one('SELECT * FROM coupons WHERE code=? AND active=1 AND expires_at>?',[$code,$this->now()]);if(!$coupon)throw new HttpError('This promotion code is not active.');if(($this->user()['role']??'')==='dealer')throw new HttpError('Retail promotion codes cannot be combined with dealer pricing.');}
        $this->db->transaction(function()use($c,$code){$this->db->run('DELETE FROM cart_coupons WHERE cart_id=?',[$c['id']]);if($code!=='')$this->db->insert('cart_coupons',['cart_id'=>$c['id'],'code'=>$code]);$this->db->run('UPDATE carts SET updated_at=? WHERE id=?',[$this->now(),$c['id']]);});return $this->cart();
    }
    public function adminVariant(array $d):array {
        $this->requireAdmin();$productId=$this->id($d,'product_id');if(!$this->db->one('SELECT id FROM products WHERE id=?',[$productId]))throw new HttpError('Product not found.',404);
        $sku=$this->text($d,'sku',100);$label=$this->text($d,'label',120);$price=filter_var($d['price_cents']??null,FILTER_VALIDATE_INT);$dealer=isset($d['dealer_price_cents'])&&$d['dealer_price_cents']!==''?filter_var($d['dealer_price_cents'],FILTER_VALIDATE_INT):null;$stock=filter_var($d['stock']??null,FILTER_VALIDATE_INT);
        if($price===false||$price<0||$price>99999999999||$dealer===false||($dealer!==null&&($dealer<0||$dealer>99999999999))||$stock===false||$stock<0||$stock>1000000)throw new HttpError('Supply valid integer prices and stock.');
        $attrs=$d['attributes']??[];if(!is_array($attrs))throw new HttpError('Variant attributes must be an object.');$attrs['source_sku']=$sku;
        $id=$this->db->transaction(function()use($d,$productId,$sku,$label,$price,$dealer,$stock,$attrs){
            if(!empty($d['id'])){$id=$this->id($d);if(!$this->db->one('SELECT id FROM product_variants WHERE id=? AND product_id=?',[$id,$productId]))throw new HttpError('Variant not found.',404);$this->db->run('UPDATE product_variants SET sku=?,label=?,price_cents=?,dealer_price_cents=?,stock=?,attributes=? WHERE id=?',[$sku,$label,$price,$dealer,$stock,json_encode($attrs),$id]);}
            else $id=$this->db->insert('product_variants',['product_id'=>$productId,'sku'=>$sku,'label'=>$label,'price_cents'=>$price,'dealer_price_cents'=>$dealer,'stock'=>$stock,'attributes'=>json_encode($attrs)]);
            $this->audit('variant.saved','variant:'.$id,['product_id'=>$productId,'price_cents'=>$price,'dealer_price_cents'=>$dealer,'stock'=>$stock]);return $id;
        });return ['variant'=>$this->variant($id),'message'=>'Variant saved.'];
    }
    public function adminCategory(array $d):array {
        $this->requireAdmin();$name=$this->text($d,'name',120);$slug=$this->text($d,'slug',80);if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))throw new HttpError('Use a URL-safe category slug.');$description=$this->text($d,'description',4000,false);$position=max(0,min(10000,(int)($d['position']??0)));
        $id=$this->db->transaction(function()use($d,$name,$slug,$description,$position){if(!empty($d['id'])){$id=$this->id($d);if(!$this->db->one('SELECT id FROM categories WHERE id=?',[$id]))throw new HttpError('Category not found.',404);$this->db->run('UPDATE categories SET name=?,slug=?,description=?,position=? WHERE id=?',[$name,$slug,$description,$position,$id]);}else$id=$this->db->insert('categories',['name'=>$name,'slug'=>$slug,'description'=>$description,'position'=>$position]);$this->audit('category.saved','category:'.$id);return $id;});return ['categories'=>$this->categories(),'message'=>'Category saved.'];
    }
    public function adminCoupon(array $d):array {
        $this->requireAdmin();$code=strtoupper($this->text($d,'code',50));if(!preg_match('/^[A-Z0-9_-]{3,50}$/',$code))throw new HttpError('Use 3–50 letters, digits, hyphens or underscores for a code.');$percent=filter_var($d['percent']??null,FILTER_VALIDATE_INT);if($percent===false||$percent<1||$percent>100)throw new HttpError('Discount percentage must be between 1 and 100.');$expires=strtotime($d['expires_at']??'');if(!$expires)throw new HttpError('Supply a valid expiry date.');$active=filter_var($d['active']??true,FILTER_VALIDATE_BOOL)?1:0;
        $this->db->transaction(function()use($code,$percent,$expires,$active){$existing=$this->db->one('SELECT code FROM coupons WHERE code=?',[$code]);if($existing)$this->db->run('UPDATE coupons SET percent=?,expires_at=?,active=? WHERE code=?',[$percent,gmdate('c',$expires),$active,$code]);else$this->db->insert('coupons',['code'=>$code,'percent'=>$percent,'expires_at'=>gmdate('c',$expires),'active'=>$active]);$this->audit('coupon.saved','coupon:'.$code,['percent'=>$percent,'active'=>$active]);});return ['message'=>'Promotion code saved.'];
    }

}
